const {event,settings}= $json;
const validId = v => typeof v==='string' && /^[A-Za-z0-9_-]{1,80}$/.test(v);
if(!settings || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(settings.teamId)) throw new Error('Set a valid Linear team UUID');
if(!validId(settings.instanceKey)||settings.instanceKey==='YOUR_INSTANCE_KEY') throw new Error('Set a stable nonsecret instanceKey');
if(typeof settings.createIssue!=='boolean') throw new Error('createIssue must be a boolean');
const origin=typeof settings.n8nBaseUrl==='string'?settings.n8nBaseUrl.replace(/\/$/,''):'';
if(!/^https:\/\/(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}(?::[0-9]{1,5})?$/.test(origin)||origin==='https://n8n.example.com') throw new Error('Set an HTTPS origin for your n8n instance');
const workflowId=event?.workflow?.id;
if(!validId(workflowId)) throw new Error('Missing workflow ID');
const executionId=event?.execution?.retryOf||event?.execution?.id;
const triggerTime=event?.trigger?.error?.timestamp;
let failureKey,executionUrl=null;
if(validId(executionId)) {failureKey='execution-'+executionId;executionUrl=origin+'/execution/'+encodeURIComponent(executionId);}
else if(Number.isSafeInteger(triggerTime)&&triggerTime>0) failureKey='trigger-'+triggerTime;
else throw new Error('No stable execution ID or trigger error timestamp; inspect source before retry');
const marker='[n8n-failure:'+settings.instanceKey+':'+workflowId+':'+failureKey+']';
const title='Automation failure for workflow '+workflowId;
const description=marker+'\n\nA workflow failed. Inspect its saved execution or trigger history in n8n.\n\nWorkflow: '+origin+'/workflow/'+encodeURIComponent(workflowId)+(executionUrl?'\nExecution: '+executionUrl:'\nTrigger failure timestamp: '+triggerTime)+'\n\nRaw error messages, input data, stack traces and customer content are intentionally omitted.';
const query='query($filter:IssueFilter!){issues(first:2,includeArchived:true,filter:$filter){nodes{id title description url team{id}} pageInfo{hasNextPage}}}';
return [{json:{settings,marker,title,description,queryBody:{query,variables:{filter:{team:{id:{eq:settings.teamId}},description:{contains:marker}}}}}}];

const p=$('Build safe failure reference').first().json;
const r=$json;
if(r.errors?.length || !r.data?.issues || !Array.isArray(r.data.issues.nodes)||typeof r.data.issues.pageInfo?.hasNextPage!=='boolean') throw new Error('Linear search incomplete or failed');
const rows=r.data.issues.nodes;
if(r.data.issues.pageInfo.hasNextPage || rows.length>1) throw new Error('Multiple recovery matches; reconcile manually');
if(rows.length && (rows[0].team?.id!==p.settings.teamId || !rows[0].description?.includes(p.marker))) throw new Error('Recovery issue identity mismatch');
if(rows.length) return [{json:{create:false,status:'existing_issue',issueId:rows[0].id,url:rows[0].url}}];
if(!p.settings.createIssue) return [{json:{create:false,status:'preview',title:p.title,description:p.description}}];
return [{json:{create:true,createBody:{query:'mutation($input:IssueCreateInput!){issueCreate(input:$input){success issue{id}}}',variables:{input:{teamId:p.settings.teamId,title:p.title,description:p.description}}}}}];

const p=$('Build safe failure reference').first().json, expected=$('Validate creation response').first().json.issueId, issue=$json.data?.issue;
if($json.errors?.length||issue?.id!==expected||issue?.team?.id!==p.settings.teamId||issue?.title!==p.title||issue?.description!==p.description||typeof issue?.url!=='string') throw new Error('Issue creation readback is unconfirmed. Inspect Linear before retrying');
return [{json:{status:'created_and_verified',issueId:issue.id,url:issue.url}}];
